-- Run once in Supabase SQL Editor. Adds reference data only; preserves profiles and plans.
begin;
create table if not exists public.career_skill_references (
  career_id text not null,
  esco_version text not null,
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  imported_at timestamptz not null default now(),
  primary key (career_id, esco_version)
);
alter table public.career_skill_references enable row level security;
revoke all on public.career_skill_references from anon, authenticated;
grant select on public.career_skill_references to authenticated;
drop policy if exists "Read ESCO reference" on public.career_skill_references;
create policy "Read ESCO reference" on public.career_skill_references
  for select to authenticated using (true);
comment on table public.career_skill_references is
  'European Commission ESCO reference snapshot. Not proficiency targets, forecasts or Malaysian vacancy evidence. Client writes denied.';


-- ESCO v1.2.1 subset from the team-supplied archive. Run after 003_esco_reference.sql.

insert into public.career_skill_references(career_id,esco_version,payload) values ('data-analyst','1.2.1','{"career_id": "data-analyst", "esco_version": "1.2.1", "occupation_uri": "http://data.europa.eu/esco/occupation/d3edb8f8-3a06-47a0-8fb9-9b212c006aa2", "occupation_label": "data analyst", "description": "Data analysts import, inspect, clean, transform, validate, model, or interpret collections of data with regard to the business goals of the company. They ensure that the data sources and repositories provide consistent and reliable data. Data analysts use different algorithms and IT tools as demanded by the situation and the current data. They might prepare reports in the form of visualisations such as graphs, charts, and dashboards.", "source_url": "https://esco.ec.europa.eu/en/use-esco/download", "archive_sha256": "f9761b0b52be1828b38a3e5e0ae59a93a7b0ce358bc800f52f57a8b002adeb3e", "mapping_note": "Team-selected related occupation; not an official equivalence or Malaysian demand evidence.", "skills": [{"uri": "http://data.europa.eu/esco/skill/47a49cd6-097d-457a-9f7b-c290c14930d5", "label": "analyse big data", "relation": "essential", "type": "skill/competence", "description": "Collect and evaluate numerical data in large quantities, especially for the purpose of identifying patterns between the data."}, {"uri": "http://data.europa.eu/esco/skill/382c11ed-20d5-4ae7-b60e-15fec527fa6c", "label": "apply statistical analysis techniques", "relation": "essential", "type": "skill/competence", "description": "Use models (descriptive or inferential statistics) and techniques (data mining or machine learning) for statistical analysis and ICT tools to analyse data, uncover correlations and forecast trends."}, {"uri": "http://data.europa.eu/esco/skill/98a1dec3-8138-4f46-a596-5e2a83b884b9", "label": "business analytics", "relation": "essential", "type": "knowledge", "description": "The disciplines and technologies for solving business problems through employing quantitative methods such as data analysis and statistical models."}, {"uri": "http://data.europa.eu/esco/skill/143769cb-b61e-47d8-a61e-eedfbec1016c", "label": "business intelligence", "relation": "essential", "type": "knowledge", "description": "The tools used to transform large amounts of raw data into relevant and helpful business information."}, {"uri": "http://data.europa.eu/esco/skill/79e29b8b-47d1-470d-b7b1-32506bfe7d9a", "label": "collect ICT data", "relation": "essential", "type": "skill/competence", "description": "Gather data by designing and applying search and sampling methods."}, {"uri": "http://data.europa.eu/esco/skill/48db96bf-3314-45c6-bad8-fdb6e20e5639", "label": "data engineering", "relation": "essential", "type": "knowledge", "description": "The process of developing and constructing systems for implementing data collection and analysis at large scale."}, {"uri": "http://data.europa.eu/esco/skill/e9575f7f-053a-439e-8074-f93df3334e92", "label": "data ethics", "relation": "essential", "type": "knowledge", "description": "The subfield of ethics that assess whether data practices are considerable ethical. It assesses processes such as collecting, analysing and disseminating structured and unstructured data that might negatively impact the society."}, {"uri": "http://data.europa.eu/esco/skill/25f0ea33-b4a2-4f31-b7b4-7d20e827b180", "label": "data mining", "relation": "essential", "type": "knowledge", "description": "The methods of artificial intelligence, machine learning, statistics and databases used to extract content from a dataset."}, {"uri": "http://data.europa.eu/esco/skill/fecf8a0d-62c4-4e71-9b03-0f4fc2ad7bf5", "label": "data models", "relation": "essential", "type": "knowledge", "description": "The techniques and existing systems used for structuring data elements and showing relationships between them, as well as methods for interpreting the data structures and relationships."}, {"uri": "http://data.europa.eu/esco/skill/cc7370dd-69fa-4c67-a96f-d4d135d38700", "label": "data quality assessment", "relation": "essential", "type": "knowledge", "description": "The process of revealing data issues using ​quality indicators, measures and metrics in order to plan data cleansing and data enrichment strategies according to data quality criteria."}, {"uri": "http://data.europa.eu/esco/skill/edebd83d-35f6-4ed5-a940-6c203d178c01", "label": "data science", "relation": "essential", "type": "knowledge", "description": "The field of study that deals with big amount of data using AI techniques such as machine learning algorithms to predict patterns and obtain useful information to make business decisions."}, {"uri": "http://data.europa.eu/esco/skill/65e58886-bd1e-4c5b-8ca5-8d9b353c8aa1", "label": "data visualisation software", "relation": "essential", "type": "knowledge", "description": "A computer tool or application that creates a graphical and visual representation of data, allowing a better understanding and interpretation of complex data through visual elements such as maps, charts, infographics or graphs."}, {"uri": "http://data.europa.eu/esco/skill/54c9c155-9293-4329-8ed2-2e76e8b519d4", "label": "define data quality criteria", "relation": "essential", "type": "skill/competence", "description": "Specify the criteria by which data quality is measured for business purposes, such as inconsistencies, incompleteness, usability for purpose and accuracy."}, {"uri": "http://data.europa.eu/esco/skill/629685b8-5f9e-4522-8cff-b3e2c4ec625a", "label": "digital data processing", "relation": "essential", "type": "", "description": "Identify, locate, retrieve, store, organise and analyse digital information, judging its relevance and purpose."}, {"uri": "http://data.europa.eu/esco/skill/327d15c8-29ff-4ad4-a4fe-6536d777a45f", "label": "documentation types", "relation": "essential", "type": "knowledge", "description": "The characteristics of internal and external documentation types aligned with the product life cycle and their specific content types."}, {"uri": "http://data.europa.eu/esco/skill/2daec0e6-f0c1-43e8-8178-aedba99130ec", "label": "establish data processes", "relation": "essential", "type": "skill/competence", "description": "Use ICT tools to apply mathematical, algorithmic or other data manipulation processes in order to create information."}, {"uri": "http://data.europa.eu/esco/skill/31c69100-b612-4a61-8db5-fd314318854c", "label": "execute analytical mathematical calculations", "relation": "essential", "type": "skill/competence", "description": "Apply mathematical methods and make use of calculation technologies in order to perform analyses and devise solutions to specific problems."}, {"uri": "http://data.europa.eu/esco/skill/4a193795-fa63-414e-9f2e-bfdb3924571e", "label": "handle data samples", "relation": "essential", "type": "skill/competence", "description": "Collect and select a set of data from a population by a statistical or other defined procedure."}, {"uri": "http://data.europa.eu/esco/skill/713fb616-118e-40bc-9366-4a69879a49d5", "label": "implement data quality processes", "relation": "essential", "type": "skill/competence", "description": "Apply quality analysis, validation and verification techniques on data to check data quality integrity."}, {"uri": "http://data.europa.eu/esco/skill/93aaf65c-5aad-4e6f-a7ba-ce9bf7c0e6e6", "label": "information categorisation", "relation": "essential", "type": "knowledge", "description": "The process of classifying the information into categories and showing relationships between the data for some clearly defined purposes."}, {"uri": "http://data.europa.eu/esco/skill/a56dec32-05ef-45de-a256-ee6741f356db", "label": "information confidentiality", "relation": "essential", "type": "knowledge", "description": "The mechanisms and regulations which allow for selective access control and guarantee that only authorised parties (people, processes, systems and devices) have access to data, the way to comply with confidential information and the risks of non-compliance."}, {"uri": "http://data.europa.eu/esco/skill/696e3b5b-8b61-45af-ae4c-3ab700f197ec", "label": "information extraction", "relation": "essential", "type": "knowledge", "description": "The techniques and methods used for eliciting and extracting information from unstructured or semi-structured digital documents and sources."}, {"uri": "http://data.europa.eu/esco/skill/03ff0d53-573a-47a0-a0ad-1995815a4339", "label": "information structure", "relation": "essential", "type": "knowledge", "description": "The type of infrastructure which defines the format of data: semi-structured, unstructured and structured."}, {"uri": "http://data.europa.eu/esco/skill/46ec0033-3c71-415e-bcff-b065675ba2dc", "label": "integrate ICT data", "relation": "essential", "type": "skill/competence", "description": "Combine data from sources to provide unified view of the set of these data."}, {"uri": "http://data.europa.eu/esco/skill/1e77e42a-181f-4b48-8e74-201ce50ffc29", "label": "interpret current data", "relation": "essential", "type": "skill/competence", "description": "Analyse data gathered from sources such as market data, scientific papers, customer requirements and questionnaires which are current and up-to-date in order to assess development and innovation in areas of expertise."}, {"uri": "http://data.europa.eu/esco/skill/9ff9db9d-d14b-426e-83f3-e7449af6c79f", "label": "manage data", "relation": "essential", "type": "skill/competence", "description": "Administer all types of data resources through their lifecycle by performing data profiling, parsing, standardisation, identity resolution, cleansing, enhancement and auditing. Ensure the data is fit for purpose, using specialised ICT tools to fulfil the data quality criteria."}, {"uri": "http://data.europa.eu/esco/skill/07889c08-7220-47c8-96f7-6068fbea00dc", "label": "normalise data", "relation": "essential", "type": "skill/competence", "description": "Reduce data to their accurate core form (normal forms) in order to achieve such results as minimisation of dependency, elimination of redundancy, increase of consistency."}, {"uri": "http://data.europa.eu/esco/skill/50b100ea-74fd-4706-99db-3e4ca55e51b8", "label": "perform data cleansing", "relation": "essential", "type": "skill/competence", "description": "Detect and correct corrupt records from data sets, ensure that the data become and remain structured according to guidelines."}, {"uri": "http://data.europa.eu/esco/skill/4216e465-7baa-4884-a241-54b197bb9278", "label": "perform data mining", "relation": "essential", "type": "skill/competence", "description": "Explore large datasets to reveal patterns using statistics, database systems or artificial intelligence and present the information in a comprehensible way."}, {"uri": "http://data.europa.eu/esco/skill/9cf681c7-89ec-470c-b651-7fe03786f586", "label": "query languages", "relation": "essential", "type": "knowledge", "description": "The field of standardised computer languages for retrieval of information from a database and of documents containing the needed information."}, {"uri": "http://data.europa.eu/esco/skill/99207709-d076-4cce-ba38-e90d3bb28806", "label": "resource description framework query language", "relation": "essential", "type": "knowledge", "description": "The query languages such as SPARQL which are used to retrieve and manipulate data stored in Resource Description Framework format (RDF)."}, {"uri": "http://data.europa.eu/esco/skill/7ee4c2ea-b349-4bd2-81a3-ec31475d4833", "label": "statistics", "relation": "essential", "type": "knowledge", "description": "The study of statistical theory, methods and practices such as collection, organisation, analysis, interpretation and presentation of data. It deals with all aspects of data including the planning of data collection in terms of the design of surveys and experiments in order to forecast and plan work-related activities."}, {"uri": "http://data.europa.eu/esco/skill/c5e8abde-d2ba-4e8e-a65e-720b71180666", "label": "unstructured data", "relation": "essential", "type": "knowledge", "description": "The information that is not arranged in a pre-defined manner or does not have a pre-defined data model and is difficult to understand and find patterns in without using techniques such as data mining."}, {"uri": "http://data.europa.eu/esco/skill/1b70a55d-b8a4-49fc-96c6-15ab4cff2522", "label": "use data processing techniques", "relation": "essential", "type": "skill/competence", "description": "Gather, process and analyse relevant data and information, properly store and update data and represent figures and data using charts and statistical diagrams."}, {"uri": "http://data.europa.eu/esco/skill/4463a721-69f3-413d-8321-43e3af13a4f1", "label": "use databases", "relation": "essential", "type": "skill/competence", "description": "Use software tools for managing and organising data in a structured environment which consists of attributes, tables and relationships in order to query and modify the stored data."}, {"uri": "http://data.europa.eu/esco/skill/348b74cd-49ce-4844-8bdf-ec188b497213", "label": "visual presentation techniques", "relation": "essential", "type": "knowledge", "description": "The visual representation and interaction techniques, such as histograms, scatter plots, surface plots, tree maps and parallel coordinate plots, that can be used to present abstract numerical and non-numerical data, in order to reinforce the human understanding of this information."}, {"uri": "http://data.europa.eu/esco/skill/e46291c7-52b9-4174-bd59-178884861038", "label": "Hadoop", "relation": "optional", "type": "knowledge", "description": "The open-source data storing, analysis and processing framework which consists mainly in the MapReduce and Hadoop distributed file system (HDFS) components and it is used to provide support for managing and analysing large datasets."}, {"uri": "http://data.europa.eu/esco/skill/a57a54b6-2f2e-43e4-9621-b52f4a63cb08", "label": "LDAP", "relation": "optional", "type": "knowledge", "description": "The computer language LDAP is a query language for retrieval of information from a database and of documents containing the needed information."}, {"uri": "http://data.europa.eu/esco/skill/c7d24594-0c11-4b27-9039-fe0bb903da8e", "label": "LINQ", "relation": "optional", "type": "knowledge", "description": "The computer language LINQ is a query language for retrieval of information from a database and of documents containing the needed information. It is developed by the software company Microsoft."}, {"uri": "http://data.europa.eu/esco/skill/1b7c716e-af95-4cda-a42f-6479c8b139f5", "label": "MDX", "relation": "optional", "type": "knowledge", "description": "The computer language MDX is a query language for retrieval of information from a database and of documents containing the needed information. It is developed by the software company Microsoft."}, {"uri": "http://data.europa.eu/esco/skill/f597f772-24d3-4cec-813c-cf5a7027c794", "label": "N1QL", "relation": "optional", "type": "knowledge", "description": "The computer language N1QL is a query language for retrieval of information from a database and of documents containing the needed information. It is developed by the software company Couchbase."}, {"uri": "http://data.europa.eu/esco/skill/5da8018b-ae85-4cde-ad93-0394369018f3", "label": "SPARQL", "relation": "optional", "type": "knowledge", "description": "The computer language SPARQL is a query language for retrieval of information from a database and of documents containing the needed information. It is developed by the international standards organisation World Wide Web Consortium."}, {"uri": "http://data.europa.eu/esco/skill/3f4dab51-572b-4e2c-85ef-3b4c3f7094e1", "label": "XQuery", "relation": "optional", "type": "knowledge", "description": "The computer language XQuery is a query language for retrieval of information from a database and of documents containing the needed information. It is developed by the international standards organisation World Wide Web Consortium."}, {"uri": "http://data.europa.eu/esco/skill/bd14968e-e409-45af-b362-3495ed7b10e0", "label": "cloud technologies", "relation": "optional", "type": "knowledge", "description": "The technologies which enable access to hardware, software, data and services through remote servers and software networks irrespective of their location and architecture."}, {"uri": "http://data.europa.eu/esco/skill/fbafa41f-cd05-4109-a649-8b44d306d779", "label": "create data models", "relation": "optional", "type": "skill/competence", "description": "Use specific techniques and methodologies to analyse the data requirements of an organisation''s business processes in order to create models for these data, such as conceptual, logical and physical models. These models have a specific structure and format."}, {"uri": "http://data.europa.eu/esco/skill/a7f0fbe0-c546-4f30-8e41-34a58c64567e", "label": "data storage", "relation": "optional", "type": "knowledge", "description": "The physical and technical concepts of how digital data storage is organised in specific schemes both locally, such as hard-drives and random-access memories (RAM) and remotely, via network, internet or cloud."}, {"uri": "http://data.europa.eu/esco/skill/43ae58b9-5e56-4524-b45a-b422777a0576", "label": "database", "relation": "optional", "type": "knowledge", "description": "The classification of databases, that includes their purpose, characteristics, terminology, models and use such as XML databases, document-oriented databases and full text databases."}, {"uri": "http://data.europa.eu/esco/skill/c3e36d05-8ae8-447f-bb2b-6f9409f85389", "label": "deliver visual presentation of data", "relation": "optional", "type": "skill/competence", "description": "Create visual representations of data such as charts or diagrams for easier understanding."}, {"uri": "http://data.europa.eu/esco/skill/8b0f73ff-d36b-4196-bb83-464c3a6ef07d", "label": "game theory", "relation": "optional", "type": "knowledge", "description": "The study of mathematical models of strategic decisions among stakeholders. It has applications in all fields of social science, as well as in systems science, computer science and logic. Essential concepts are the Nash Equilibrium and the Prisoner''s Dilemma."}, {"uri": "http://data.europa.eu/esco/skill/0c766ca3-9364-4203-916b-fed16e4814c1", "label": "gather data for forensic purposes", "relation": "optional", "type": "skill/competence", "description": "Collect protected, fragmented or corrupted data and other online communication. Document and present findings from this process."}, {"uri": "http://data.europa.eu/esco/skill/a1eef0f4-133f-464a-a8f1-68fe3e8cc1b4", "label": "healthcare analytics", "relation": "optional", "type": "knowledge", "description": "The use of qualitative and quantitative methods to analyse patterns in healthcare data to the aim of improving healthcare administration, quality in patient care and diseases diagnosis."}, {"uri": "http://data.europa.eu/esco/skill/45f1ae17-c20d-40fc-9307-7d33b6ca9213", "label": "image recognition", "relation": "optional", "type": "knowledge", "description": "A process designed to detect and identify a feature or object in an image or video. This process is used in medical imaging, security surveillance or defect detection, among other fields. Key technique for a wide range of applications such as automated driving, image classification, or visual inspection."}, {"uri": "http://data.europa.eu/esco/skill/1bba98a7-92b9-450b-9235-e0c905f8f3c4", "label": "information architecture", "relation": "optional", "type": "knowledge", "description": "The methods through which information is generated, structured, stored, maintained, linked, exchanged and used."}, {"uri": "http://data.europa.eu/esco/skill/be20d05c-f6b4-4580-9fcf-f00f4baab562", "label": "make data-driven decisions", "relation": "optional", "type": "skill/competence", "description": "Collect data such as Key Performance Indicators (KPIs) for an organisation and use the information to formulate actions and strategies."}, {"uri": "http://data.europa.eu/esco/skill/d3286405-49f8-4e8a-8046-a4376b4e7963", "label": "manage cloud data and storage", "relation": "optional", "type": "skill/competence", "description": "Create and manage cloud data retention. Identify and implement data protection, encryption, and capacity planning needs."}, {"uri": "http://data.europa.eu/esco/skill/a80fb090-63f4-4b05-83a5-2f090deb7757", "label": "manage data collection systems", "relation": "optional", "type": "skill/competence", "description": "Develop and manage methods and strategies used to maximise data quality and statistical efficiency in the collection of data, in order to ensure the gathered data are optimised for further processing."}, {"uri": "http://data.europa.eu/esco/skill/57231a22-4da7-49c8-97b8-75672feadf1e", "label": "manage quantitative data", "relation": "optional", "type": "skill/competence", "description": "Gather, process and present quantitative data. Use the appropriate programs and methods for validating, organising and interpreting data."}, {"uri": "http://data.europa.eu/esco/skill/11c56452-fcec-4b00-9695-cca4728e5048", "label": "marketing analytics", "relation": "optional", "type": "knowledge", "description": "The set of processes for employing data to improve the effectiveness of marketing activities. It involves analysing metrics such as the Return on Investment (ROI) for identify opportunities of improvement."}, {"uri": "http://data.europa.eu/esco/skill/9fc400ac-8ed2-4aff-915f-aa4f2609ec7b", "label": "multidisciplinary research", "relation": "optional", "type": "knowledge", "description": "The research technique where a common issue is investigated using approaches from different disciplines with the aim of finding a comprehensive solution to it."}, {"uri": "http://data.europa.eu/esco/skill/b0a3bb25-a02f-43ed-ab1f-994fa66a424a", "label": "online analytical processing", "relation": "optional", "type": "knowledge", "description": "The online tools which analyse, aggregate and present multi-dimensional data enabling users to interactively and selectively extract and view data from specific points of view."}, {"uri": "http://data.europa.eu/esco/skill/c544a9f3-5945-4b54-afed-de0697852817", "label": "report analysis results", "relation": "optional", "type": "skill/competence", "description": "Produce research documents or give presentations to report the results of a conducted research and analysis project, indicating the analysis procedures and methods which led to the results, as well as potential interpretations of the results."}, {"uri": "http://data.europa.eu/esco/skill/7159e587-c7cb-4ec0-a662-03e1dee2cccb", "label": "research design", "relation": "optional", "type": "knowledge", "description": "The set of methods and techniques of research that are used to conduct a study. It includes practical steps in research such as purpose statement, data collection, methodology, and data analysis."}, {"uri": "http://data.europa.eu/esco/skill/33e584f9-ff7a-4979-bfc0-5a3a374a145a", "label": "social network analysis", "relation": "optional", "type": "knowledge", "description": "The research method that is mainly explored in sociology and communication science and focuses on the analysis of the relations between individuals and among organisations and states."}, {"uri": "http://data.europa.eu/esco/skill/68ef0e4d-5542-4e64-84f4-752cce5a3c22", "label": "statistical modeling techniques", "relation": "optional", "type": "knowledge", "description": "The approaches for employing statistical analysis to dataset within the data science field. It seeks to elaborate reality predictions through statistical models and explicit assumptions."}, {"uri": "http://data.europa.eu/esco/skill/611ed16b-99bf-4840-9cab-f55d1d286e0a", "label": "store digital data and systems", "relation": "optional", "type": "skill/competence", "description": "Use software tools to archive data by copying and backing them up, in order to ensure their integrity and to prevent data loss."}, {"uri": "http://data.europa.eu/esco/skill/1973c966-f236-40c9-b2d4-5d71a89019be", "label": "use spreadsheets software", "relation": "optional", "type": "skill/competence", "description": "Use software tools to create and edit tabular data to carry out mathematical calculations, organise data and information, create diagrams based on data and to retrieve them."}, {"uri": "http://data.europa.eu/esco/skill/1605025e-a179-421f-8f35-5b07d182a6b2", "label": "web analytics", "relation": "optional", "type": "knowledge", "description": "The characteristics, tools and techniques for measurement, collection, analysis and reporting of web data to get information on the users'' behaviour and to improve the performance of a website."}]}'::jsonb) on conflict(career_id,esco_version) do update set payload=excluded.payload, imported_at=now();
insert into public.career_skill_references(career_id,esco_version,payload) values ('software-engineer','1.2.1','{"career_id": "software-engineer", "esco_version": "1.2.1", "occupation_uri": "http://data.europa.eu/esco/occupation/f2b15a0e-e65a-438a-affb-29b9d50b77d1", "occupation_label": "software developer", "description": "Software developers implement or program all kinds of software systems based on specifications and designs by using programming languages, tools, and platforms.", "source_url": "https://esco.ec.europa.eu/en/use-esco/download", "archive_sha256": "f9761b0b52be1828b38a3e5e0ae59a93a7b0ce358bc800f52f57a8b002adeb3e", "mapping_note": "Team-selected related occupation; not an official equivalence or Malaysian demand evidence.", "skills": [{"uri": "http://data.europa.eu/esco/skill/6014921e-1d25-4039-adc2-04852d61880e", "label": "ICT debugging tools", "relation": "essential", "type": "knowledge", "description": "The ICT tools used to test and debug programs and software code, such as GNU Debugger (GDB), Intel Debugger (IDB), Microsoft Visual Studio Debugger, Valgrind and WinDbg."}, {"uri": "http://data.europa.eu/esco/skill/f28617ad-afdd-4041-814c-216153a38998", "label": "analyse software specifications", "relation": "essential", "type": "skill/competence", "description": "Assess the specifications of a software product or system to be developed by identifying functional and non-functional requirements, constraints and possible sets of use cases which illustrate interactions between the software and its users."}, {"uri": "http://data.europa.eu/esco/skill/21d2f96d-35f7-4e3f-9745-c533d2dd6e97", "label": "computer programming", "relation": "essential", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of programming paradigms (e.g. object oriented programming, functional programming) and of programming languages."}, {"uri": "http://data.europa.eu/esco/skill/901105f8-3a08-453e-b1dc-23619e317fd3", "label": "create flowchart diagram", "relation": "essential", "type": "skill/competence", "description": "Compose a diagram that illustrates systematic progress through a procedure or system using connecting lines and a set of symbols."}, {"uri": "http://data.europa.eu/esco/skill/2522a6ce-3202-4ac8-9f5b-b9cb5a3a83a1", "label": "debug software", "relation": "essential", "type": "skill/competence", "description": "Repair computer code by analysing testing results, locating the defects causing the software to output an incorrect or unexpected result and remove these faults."}, {"uri": "http://data.europa.eu/esco/skill/d9e5349e-8791-49c2-8ba4-839fdd1606c2", "label": "define technical requirements", "relation": "essential", "type": "skill/competence", "description": "Specify technical properties of goods, materials, methods, processes, services, systems, software and functionalities by identifying and responding to the particular needs that are to be satisfied according to customer requirements."}, {"uri": "http://data.europa.eu/esco/skill/0b0335f3-0aa1-491e-895e-81fc8774a300", "label": "develop automated migration methods", "relation": "essential", "type": "skill/competence", "description": "Create automated transfer of ICT information between storage types, formats and systems to save human resources from performing the task manually."}, {"uri": "http://data.europa.eu/esco/skill/797a4416-0b8d-44f3-8fcd-eb10bd0be6b4", "label": "develop software prototype", "relation": "essential", "type": "skill/competence", "description": "Create a first incomplete or preliminary version of a piece of software application to simulate some specific aspects of the final product."}, {"uri": "http://data.europa.eu/esco/skill/209a5498-3449-4689-8ed9-bd08cab4fd78", "label": "engineering principles", "relation": "essential", "type": "knowledge", "description": "The engineering elements like functionality, replicability, and costs in relation to the design and how they are applied in the completion of engineering projects."}, {"uri": "http://data.europa.eu/esco/skill/72a74f69-5cf1-43c5-99b9-62a444578919", "label": "engineering processes", "relation": "essential", "type": "knowledge", "description": "The systematic approach to the development and maintenance of engineering systems."}, {"uri": "http://data.europa.eu/esco/skill/0e0c9c11-b39e-43cf-ba95-2fe646f5de64", "label": "identify customer requirements", "relation": "essential", "type": "skill/competence", "description": "Apply techniques and tools, such as surveys, questionnaires, ICT applications, for eliciting, defining, analysing, documenting and maintaining user requirements from system, service or product."}, {"uri": "http://data.europa.eu/esco/skill/925463a7-d51f-4d5b-9f79-4d28cf30acde", "label": "integrated development environment software", "relation": "essential", "type": "knowledge", "description": "The suite of software development tools for writing programs, such as compiler, debugger, code editor, code highlights, packaged in a unified user interface, such as Visual Studio or Eclipse."}, {"uri": "http://data.europa.eu/esco/skill/be48353d-25c7-4f86-bea9-7b9e248fbc6e", "label": "interpret technical requirements", "relation": "essential", "type": "skill/competence", "description": "Analyse, understand and apply the information provided regarding technical conditions."}, {"uri": "http://data.europa.eu/esco/skill/6a899482-8bcf-40ca-ae67-579a1cc467ab", "label": "manage engineering project", "relation": "essential", "type": "skill/competence", "description": "Manage engineering project resources, budget, deadlines, and human resources, and plan schedules as well as any technical activities pertinent to the project."}, {"uri": "http://data.europa.eu/esco/skill/4fabca9a-7435-4f33-b1da-3cdb00340fdc", "label": "perform scientific research", "relation": "essential", "type": "skill/competence", "description": "Gain, correct or improve knowledge about phenomena by using scientific methods and techniques, based on empirical or measurable observations."}, {"uri": "http://data.europa.eu/esco/skill/7111b95d-0ce3-441a-9d92-4c75d05c4388", "label": "project management", "relation": "essential", "type": "knowledge", "description": "The discipline of project management, the activities which comprise this area and the variables implied in it, such as time, resources, requirements, deadlines, and responding to unexpected events."}, {"uri": "http://data.europa.eu/esco/skill/59ea80e1-463a-4dba-82c6-d0b6d577d532", "label": "technical drawings", "relation": "essential", "type": "knowledge", "description": "Drawing software and the various symbols, perspectives, units of measurement, notation systems, visual styles and page layouts used in technical drawings."}, {"uri": "http://data.europa.eu/esco/skill/9d2e926f-53d9-41f5-98f3-19dfaa687f3f", "label": "tools for software configuration management", "relation": "essential", "type": "knowledge", "description": "The software programs to perform configuration identification, control, status accounting and audit, such as CVS, ClearCase, Subversion, GIT and TortoiseSVN perform this management."}, {"uri": "http://data.europa.eu/esco/skill/04fe962b-4017-4eb7-9139-7d69b6922bc9", "label": "use an application-specific interface", "relation": "essential", "type": "skill/competence", "description": "Understand and use interfaces particular to an application or use case."}, {"uri": "http://data.europa.eu/esco/skill/2b7a79e5-84d8-4880-be66-3d9bb05bea17", "label": "use software design patterns", "relation": "essential", "type": "skill/competence", "description": "Utilise reusable solutions, formalised best practices, to solve common ICT development tasks in software development and design."}, {"uri": "http://data.europa.eu/esco/skill/8b94aa1e-89c9-459d-b3b4-1dfab8dec2df", "label": "use software libraries", "relation": "essential", "type": "skill/competence", "description": "Utilise collections of codes and software packages which capture frequently used routines to help programmers simplify their work."}, {"uri": "http://data.europa.eu/esco/skill/541561bc-510c-4a99-881c-2d8bf5a85462", "label": "use technical drawing software", "relation": "essential", "type": "skill/competence", "description": "Create technical designs and technical drawings using specialised software."}, {"uri": "http://data.europa.eu/esco/skill/172020d1-e151-445b-8173-e2a5fb16fe51", "label": "utilise computer-aided software engineering tools", "relation": "essential", "type": "skill/competence", "description": "Use software tools (CASE) to support the development lifecycle, design and implementation of software and applications of high-quality that can be easily maintained."}, {"uri": "http://data.europa.eu/esco/skill/f84a433f-34f1-4083-b0a3-24802623509c", "label": "web services", "relation": "essential", "type": "knowledge", "description": "XML-based information systems that allows for direct interactions between applications through Internet. It is a set of protocols for transferring data between applications and systems."}, {"uri": "http://data.europa.eu/esco/skill/eb0e5615-1575-4a86-a1a2-7d39595033c5", "label": "ABAP", "relation": "optional", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of programming paradigms in ABAP."}, {"uri": "http://data.europa.eu/esco/skill/b4dc6e4f-dc7d-445f-8ce2-d7b9d225e282", "label": "AJAX", "relation": "optional", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of programming paradigms in AJAX."}, {"uri": "http://data.europa.eu/esco/skill/58d7a289-dafd-4363-833f-d1dc4140885e", "label": "APL", "relation": "optional", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of programming paradigms in APL."}, {"uri": "http://data.europa.eu/esco/skill/56a7f561-1d55-43c9-9cd7-36a0a9bc6c50", "label": "ASP.NET", "relation": "optional", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of programming paradigms in ASP.NET."}, {"uri": "http://data.europa.eu/esco/skill/8c88d336-c249-4537-b26e-d679a85c4b9b", "label": "Ajax Framework", "relation": "optional", "type": "knowledge", "description": "The Ajax software development environments which provide specific features and components that support and guide web applications development."}, {"uri": "http://data.europa.eu/esco/skill/6f8a40d6-f9ce-43ec-a72f-d4213a53f3ed", "label": "Ansible", "relation": "optional", "type": "knowledge", "description": "The tool Ansible is a software program to perform configuration identification, control, status accounting and audit."}, {"uri": "http://data.europa.eu/esco/skill/0d168770-4d9c-4096-b048-a6577818d306", "label": "Apache Maven", "relation": "optional", "type": "knowledge", "description": "The tool Apache Maven is a software program to perform configuration identification, control, status accounting and audit of software during its development and maintenance."}, {"uri": "http://data.europa.eu/esco/skill/0fb753a1-2ef2-4429-84d2-ecb2b24daf7a", "label": "Apache Tomcat", "relation": "optional", "type": "knowledge", "description": "The open-source web server Apache Tomcat provides a Java web server environment which uses a built in container where HTTP requests are loaded, allowing the Java web applications to run on local and server based systems."}, {"uri": "http://data.europa.eu/esco/skill/47b9bbcf-356c-4782-83a4-7f5a1b2b51a3", "label": "Assembly (computer programming)", "relation": "optional", "type": "knowledge", "description": "The techniques and principles of software development, such as analysis, algorithms, coding, testing and compiling of program